(() => { const G = window.CITY.GEO; let best = null, nxt = null;
for (const d of G.decks) if (d[0] === 'Gardiner Expressway') { const a = d[3]; for (let i = 0; i + 3 < a.length; i += 3) if (!best || Math.abs(a[i] - -1300) < Math.abs(best[0] - -1300)) { best = [a[i], a[i + 1], a[i + 2]]; nxt = [a[i + 3], a[i + 4]]; } }
const [gx, gz, gh] = best; let ux = nxt[0] - gx, uz = nxt[1] - gz; const L = Math.hypot(ux, uz); ux /= L; uz /= L;
window.__CITY_APP.teleportTo(gx + uz * 40, gz - ux * 40, 0);
const px = gx - ux * 0 + uz * 0, pz = gz - uz * 0 - ux * 0;
window.__CITY_APP.cameraSystem.cinema = () => ({ pos: [px, gh + 2.4, pz], look: [px + ux * 120, gh + 2.4 + 0, pz + uz * 120], fov: 60 });
})()

